package com.foodydelivery.tracker.order; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService service;public OrderController(OrderService s){service=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public OrderDtos.Response create(@Valid @RequestBody OrderDtos.CreateRequest r,Authentication a){return service.create(r,a.getName());} @GetMapping public List<OrderDtos.Response> list(Authentication a){return service.list(a.getName());} @GetMapping("/{id}") public OrderDtos.Response get(@PathVariable Long id,Authentication a){return service.get(id,a.getName());} @PatchMapping("/{id}/status") public OrderDtos.Response status(@PathVariable Long id,@Valid @RequestBody OrderDtos.StatusRequest r,Authentication a){return service.updateStatus(id,r,a.getName());}}
